 reviews.append({'id':f'REV-{q["id"]}-v{q["version"]}-independent-interface','questionId':q['id'],'questionVersion':q['version'],'questionSha256':question_hash(q),'reviewerId':REVIEWER,'decision':'flagged' if f else 'verified','reviewedAt':now,'sourceVersions':{c['sourceId']:c['sourceSha256'] for c in q['citations']},'reviewedSlideIds':list(dict.fromkeys(c['slideId'] for c in q['citations'])),'independentAnswerOptionIds':a['independentAnswerOptionIds'],'solvedBeforeAnswerSeen':True,'checks':{k:k not in f for k in CHECK_KEYS},'reasoning':reasoning,'findings':[k+': '+v for k,v in f.items()]})
